<?php require_once '../includes/functions.php';require_user();verify_csrf();$id=(int)$_POST['place_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']);if($comment!==''){$pdo->prepare('INSERT INTO reviews(user_id,place_id,rating,comment,status) VALUES(?,?,?,?,"pending")')->execute([user()['id'],$id,$rating,$comment]);$_SESSION['flash']='Review submitted and awaiting admin approval.';}redirect('place.php?slug='.$pdo->query('SELECT slug FROM places WHERE id='.$id)->fetchColumn().'#reviews');?>